// Route Overlap Audit — DOM wiring.
// Imports the controller (state machine) and the messages; creates the
// module Worker from the build-generated worker source string.
// worker-source.mjs is generated by scripts/build.mjs into dist-preview/js/
// from the fixed core source + worker handler; it is not a source file.
import { createController, REPORT_FILENAME } from './controller.mjs';
import { MESSAGES } from './messages.mjs';
import { WORKER_SOURCE } from './worker-source.mjs';

const PAGE_SIZE = 25;

const lang = document.documentElement.lang.startsWith('zh') ? 'zh' : 'en';
const t = MESSAGES[lang];

const EXAMPLE_ROUTES = 'GET\t/users/:id\nGET\t/users/new\nPOST\t/users/new\nGET\t/users/*rest';

const routesField = document.getElementById('routes');
const runButton = document.getElementById('run');
const exampleButton = document.getElementById('example');
const resetButton = document.getElementById('reset');
const cancelButton = document.getElementById('cancel');
const downloadButton = document.getElementById('download');
const statusRegion = document.getElementById('status');
const errorRegion = document.getElementById('error');
const noticeRegion = document.getElementById('notice');
const resultsSection = document.getElementById('results');
const summaryLine = document.getElementById('summary');
const noOverlapsLine = document.getElementById('no-overlaps');
const tableWrap = document.getElementById('table-wrap');
const resultsBody = document.getElementById('results-body');
const prevButton = document.getElementById('prev-page');
const nextButton = document.getElementById('next-page');
const pageLabel = document.getElementById('page-label');

let workerUrl = null;
let downloadUrl = null;
let downloadTimer = null;
let currentPage = 1;
let lastRunDraftLines = [];

function revokeDownloadUrl() {
  if (downloadTimer !== null) {
    clearTimeout(downloadTimer);
    downloadTimer = null;
  }
  if (downloadUrl !== null) {
    URL.revokeObjectURL(downloadUrl);
    downloadUrl = null;
  }
}

function formatError(error) {
  if (!error) return '';
  const key = `error${error.code}`;
  const entry = t[key];
  if (typeof entry === 'function') return entry(error.row);
  if (typeof entry === 'string') return entry;
  return t.errorINTERNAL;
}

function patternForLine(lineNumber) {
  const line = lastRunDraftLines[lineNumber - 1];
  if (typeof line !== 'string') return '';
  const tab = line.indexOf('\t');
  return tab === -1 ? '' : line.slice(tab + 1);
}

function renderTable(result) {
  const overlaps = result.overlaps;
  const pages = Math.max(1, Math.ceil(overlaps.length / PAGE_SIZE));
  if (currentPage > pages) currentPage = pages;
  const start = (currentPage - 1) * PAGE_SIZE;
  const slice = overlaps.slice(start, start + PAGE_SIZE);
  resultsBody.replaceChildren();
  for (const overlap of slice) {
    const row = document.createElement('tr');
    const methodCell = document.createElement('td');
    methodCell.textContent = overlap.method;
    const firstCell = document.createElement('td');
    firstCell.textContent = `${t.lineLabel(overlap.first)} ${patternForLine(overlap.first)}`;
    const secondCell = document.createElement('td');
    secondCell.textContent = `${t.lineLabel(overlap.second)} ${patternForLine(overlap.second)}`;
    const witnessCell = document.createElement('td');
    const witnessCode = document.createElement('code');
    witnessCode.textContent = overlap.witness;
    witnessCell.append(witnessCode);
    row.append(methodCell, firstCell, secondCell, witnessCell);
    resultsBody.append(row);
  }
  const showPager = overlaps.length > PAGE_SIZE;
  prevButton.hidden = !showPager;
  nextButton.hidden = !showPager;
  pageLabel.hidden = !showPager;
  if (showPager) {
    prevButton.disabled = currentPage <= 1;
    nextButton.disabled = currentPage >= pages;
    pageLabel.textContent = t.pageLabel(currentPage, pages);
  }
}

function render(snapshot) {
  const { state, draft, result, reportAvailable, error } = snapshot;

  if (routesField.value !== draft.routes) routesField.value = draft.routes;

  runButton.disabled = state === 'busy';
  cancelButton.hidden = state !== 'busy';
  downloadButton.hidden = !reportAvailable;

  const statusText = {
    empty: t.statusEmpty,
    dirty: t.statusDirty,
    busy: t.statusBusy,
    success: t.statusSuccess,
    error: t.statusError,
    cancelled: t.statusCancelled,
  }[state] || '';
  statusRegion.textContent = statusText;
  statusRegion.dataset.state = state;
  statusRegion.setAttribute('aria-busy', state === 'busy' ? 'true' : 'false');

  if (error) {
    errorRegion.textContent = `${t.errorPrefix}${formatError(error)}`;
    errorRegion.hidden = false;
    routesField.setAttribute('aria-invalid', 'true');
    routesField.setAttribute('aria-errormessage', 'error');
  } else {
    errorRegion.textContent = '';
    errorRegion.hidden = true;
    routesField.removeAttribute('aria-invalid');
    routesField.removeAttribute('aria-errormessage');
  }

  if (state !== 'success' || !result) {
    resultsSection.hidden = true;
    if (state !== 'success') revokeDownloadUrl();
    return;
  }
  lastRunDraftLines = draft.routes.split('\n');
  resultsSection.hidden = false;
  summaryLine.textContent = t.summary(result.routeCount, result.overlaps.length);
  const empty = result.overlaps.length === 0;
  noOverlapsLine.hidden = !empty;
  tableWrap.hidden = empty;
  if (!empty) renderTable(result);
}

function createWorker() {
  if (workerUrl === null) {
    workerUrl = URL.createObjectURL(new Blob([WORKER_SOURCE], { type: 'text/javascript' }));
  }
  return new Worker(workerUrl, { type: 'module' });
}

const controller = createController({ createWorker });
controller.subscribe(render);

routesField.addEventListener('input', () => {
  noticeRegion.textContent = '';
  controller.setDraft(routesField.value);
});

runButton.addEventListener('click', () => {
  noticeRegion.textContent = '';
  const before = controller.getState();
  controller.runAudit();
  const after = controller.getState();
  if (after.state === 'error' && before.state !== 'error') {
    routesField.focus();
  }
});

exampleButton.addEventListener('click', () => {
  controller.setDraft(EXAMPLE_ROUTES);
  noticeRegion.textContent = t.exampleLoaded;
  routesField.focus();
});

resetButton.addEventListener('click', () => {
  noticeRegion.textContent = '';
  revokeDownloadUrl();
  currentPage = 1;
  lastRunDraftLines = [];
  controller.reset();
  routesField.focus();
});

cancelButton.addEventListener('click', () => {
  controller.cancel();
});

downloadButton.addEventListener('click', () => {
  const snapshot = controller.getState();
  if (!snapshot.report || !snapshot.result) return;
  revokeDownloadUrl();
  const blob = new Blob([snapshot.report.text], { type: 'application/json' });
  downloadUrl = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = downloadUrl;
  anchor.download = REPORT_FILENAME;
  document.body.append(anchor);
  anchor.click();
  anchor.remove();
  downloadTimer = setTimeout(revokeDownloadUrl, 30000);
});

prevButton.addEventListener('click', () => {
  const snapshot = controller.getState();
  if (!snapshot.result) return;
  if (currentPage > 1) {
    currentPage -= 1;
    renderTable(snapshot.result);
  }
});

nextButton.addEventListener('click', () => {
  const snapshot = controller.getState();
  if (!snapshot.result) return;
  const pages = Math.max(1, Math.ceil(snapshot.result.overlaps.length / PAGE_SIZE));
  if (currentPage < pages) {
    currentPage += 1;
    renderTable(snapshot.result);
  }
});

window.addEventListener('pagehide', () => {
  revokeDownloadUrl();
  controller.dispose();
  if (workerUrl !== null) {
    URL.revokeObjectURL(workerUrl);
    workerUrl = null;
  }
});

document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') {
    controller.dispose();
  }
});

window.addEventListener('pageshow', (event) => {
  if (event.persisted) controller.reset();
});

render(controller.getState());
